# urgent corrections (duty desk incident)
# --------------------------------------------------------------------------- #
def incident_ticket(entries):
    """Origin of the per-channel keys: urgent-0327-A / urgent-0327-B -> urgent-0327."""
    names = set()
    for channel, entry in entries.items():
        key = entry.get("key") or ""
